const langs=['zh','en','fr','es','eu'],T=(k,lang=A()?.prefs().language)=>words[k]?.[Math.max(0,langs.indexOf(lang))]||k;
let dialog=null,origin=null,tab='document',resultId='',filter='suggested',scale=1,map='mindmap';
